import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"27、【頤】 震下艮上","description":"周易尚氏學 - 27、【頤】 震下艮上","frontmatter":{"title":"27、【頤】 震下艮上","description":"周易尚氏學 - 27、【頤】 震下艮上"},"headers":[],"relativePath":"classics/shangshi/032.md","filePath":"classics/shangshi/032.md"}'),s={name:"classics/shangshi/032.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_27、【頤】-震下艮上" tabindex="-1">27、【頤】 震下艮上 <a class="header-anchor" href="#_27、【頤】-震下艮上" aria-label="Permalink to “27、【頤】 震下艮上”">​</a></h1><p>鄭玄曰。頤者口車輔也。震動於下。艮止於上。口車動而上。因輔嚼物以養人。故謂之頤。按左傳輔車相依注。輔輔頰。車牙車。凡物入口。牙車載之。故曰車。輔在上不動。車在下動而上。故曰因輔嚼物。頤上艮。輔也。不動者也。下震。牙車也。動而上。因輔以嚼物者也。故鄭釋最得卦義。頤能養人。故貞吉。艮為觀為求。震為口。坤為物。故曰口實。實者食也。言口合物以自養也。虞翻謂離為目。鄭玄謂二五皆離變故能觀。豈知艮一陽在上為光明。為目。為觀。象失傳。詳焦氏易詁不必用卦變及爻位也。</p><p>彖曰。頤貞吉。養正則吉也。觀頤。觀其所養也。自求口實。現其自養也。天地養萬物。聖人養賢以及萬民。頤之時大矣哉。</p><p>天地謂初上。坤為萬物為民。艮為君子為賢。伏乾為聖人。</p><p>象曰。山下有雷。頤。君子以慎言語。節飲食。</p><p>艮為君子。震為言為食。正反震言語相背。有相訟意。慎則訟息。飲食者人之所欲。震為口。正反艮手相對。有爭意。節則飲食平。慎與節皆艮止象。此易用覆象。最為神妙之語。舊說。惟易林能闡其義。說詳焦氏易詁。</p><p>初九。舍爾靈龜。觀我朵頤。 兇。</p><p>離為龜。以剛在外。艮亦剛在外。故頤。損。益皆以艮為龜。此其義。唯易林知之。屯之震雲。龜鱉列市。以震互艮為龜。泰之節雲。龜厭河海。以節互艮為龜。虞翻用卦變。以晉離為龜。易取象無此迂曲也。初爻艮覆。故曰舍爾靈龜。朵。釋文雲動也。人食物則頤動。初應在四。四當頤中。故曰觀我朵頤。言初當位。擁有群陰。貞靜自養。斯亦足矣。乃舍其自有之靈寶。而闡觀他人之寵祿。四艮體艮為貴為官則躁竟貽譏。而殃咎或至。故曰兇。按初當位有應。前臨重陰。陽遇陰則通。本無兇理。隨初。出門有功。益初。利用為大作。其證也。此則兇者。以艮震相反覆。內動外止。故宜靜不宜動。屯初雲。利居貞。是其義也。屯初至五。亦頤也。由此悟隨初有功者。以外兌。兌悅震喜。益初利用為大作者。以外巽。同聲相應。故皆動而吉。獨屯。初利居貞以外坎。無為險難。故宜貞定。其故全在外卦。頤外艮。又止故不宜動。舊解皆不詳兇之故何在。則易理失傳。不能觀其會通也。</p><h3 id="象曰。觀我朵頤。亦不足貴也。" tabindex="-1">象曰。觀我朵頤。亦不足貴也。 <a class="header-anchor" href="#象曰。觀我朵頤。亦不足貴也。" aria-label="Permalink to “象曰。觀我朵頤。亦不足貴也。”">​</a></h3><p>言初本可貴。反因妄動而不足貴也。</p><p>六二。顛頤。拂經。於丘頤。徵兇。</p><p>顛與闡（內真）通。和玉藻。盛氣顛寶。注顛讀為間（內真）。而聞（內真）與穴（下真）通。前漢遊俠傳。人無賢不肖門（內真）門。注門（內真）與穴（下真）字同。穴（下真）塞也。三四五皆陰。故曰穴（下真）頤。丘前漢息夫躬傳。寄宿丘亭。師古云。丘空也。經常。拂違也。丘頤空頤也。蓋頤以空為用。今乃穴（下真）塞。違頤之常。故曰穴（下真）頤。拂經於丘頤。前得敵故徵兇。其以顛頤拂經為句。或以拂經於丘為句者。非。</p><h3 id="象曰。六二徵兇。行失類也。" tabindex="-1">象曰。六二徵兇。行失類也。 <a class="header-anchor" href="#象曰。六二徵兇。行失類也。" aria-label="Permalink to “象曰。六二徵兇。行失類也。”">​</a></h3><p>二無應。前遇重陰。陰遇陰則窒。故曰徵兇。陰陽相遇方為類。今六二不遇陽。故曰失類。象義如此明白。乃二千年易家。皆以陰遇陰為類。於是文言之各從其類。坤彖傳之乃與類行。繫辭之方以類聚。及此皆失解。與朋友同。說詳焦氏易詁。</p><p>六三。拂頤。貞兇。十年勿用。無攸利。</p><p>吳先生曰。拂頤猶不可口也。貞佔也。坤為十年。三不當位。承乘皆陰。故十年不用。無攸利也。按三有應。陰得陽應多吉。此獨不吉者。以四五得敵。應上甚難。故曰無攸利。</p><h3 id="象曰。十年勿用。道大悖也" tabindex="-1">象曰。十年勿用。道大悖也 <a class="header-anchor" href="#象曰。十年勿用。道大悖也" aria-label="Permalink to “象曰。十年勿用。道大悖也”">​</a></h3><p>艮震皆為道路。乃艮震上下象皆相反。故日道大悖。玉篇悖逆也。言艮震皆有覆象相逆也。艮震皆為道。乃上卦覆震。與下震相逆。下卦覆艮。與上艮相逆。象下一悖字。尋味無窮。</p><p>六四。顛頤。吉。虎視眈眈。其欲逐逐。無咎。</p><p>六二無應。以陰穴（下真）頤。故兇。六四有應。穴（下真）頤以陽。故吉。艮為虎為視。眈眈視貌。說文雲視近志遠。坤為欲。逐逐言所欲在初。乃為二三所阻。不能遽遂其欲。故逐逐不已。</p><h3 id="象曰。顛顧之吉。上施光也。" tabindex="-1">象曰。顛顧之吉。上施光也。 <a class="header-anchor" href="#象曰。顛顧之吉。上施光也。" aria-label="Permalink to “象曰。顛顧之吉。上施光也。”">​</a></h3><p>初陽應四。故曰上施光。三有應不當位。故兇。四當位有應。故吉。然四雖有應。為二三所隔。難以下施。故須初上施而吉也。</p><p>六五。拂經。居貞吉。不可涉大川。</p><p>拂經。王注作拂頤。五不當位。故拂頤。居安也。安居五位。順上承陽。故貞吉。若下涉坤水。陰遇陰則窒。故不可也。</p><h3 id="象曰。居貞之吉。順以從上也。" tabindex="-1">象曰。居貞之吉。順以從上也。 <a class="header-anchor" href="#象曰。居貞之吉。順以從上也。" aria-label="Permalink to “象曰。居貞之吉。順以從上也。”">​</a></h3><p>上陽。故當順從。</p><p>上九。由顧。厲吉。利涉大川。</p><p>由自得也。義詳豫九四。九四下乘重陰。故曰由豫。此亦下乘重陰。放曰由頤。然高居萬民之上。恐逸豫隨之。故振厲方吉也。坤為大川。陽遇陰則通。故利涉大川。此與五爻舊解所以全誤者。一由坤水象失傳。必用虞翻再三變之法。始得坎為大川。二由類字失詁。故不知和涉不利涉之故何在也。</p><h3 id="象曰。由頤厲吉。大有慶也。" tabindex="-1">象曰。由頤厲吉。大有慶也。 <a class="header-anchor" href="#象曰。由頤厲吉。大有慶也。" aria-label="Permalink to “象曰。由頤厲吉。大有慶也。”">​</a></h3><p>大有慶。謂上九乘重陰。</p>',30)])])}const f=e(s,[["render",t]]);export{_ as __pageData,f as default};
